package com.starcase.archive;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.X509EncodedKeySpec;import java.util.*;import org.json.*;

final class UpdateProtocol {
 static final String CURRENT="0.1.1", REPO="https://github.com/Feathercatttt/starcase-archive/", MANIFEST="https://raw.githubusercontent.com/Feathercatttt/starcase-archive/main/updates/stable.json";
 static final String[] MIRRORS={"https://gh-proxy.org/","https://ghfast.top/","https://ghproxy.net/",""};
 static int compare(String a,String b)throws Exception{if(!a.matches("\\d{1,4}\\.\\d{1,4}\\.\\d{1,4}")||!b.matches("\\d{1,4}\\.\\d{1,4}\\.\\d{1,4}"))throw new IOException("更新版本格式无效");String[] x=a.split("\\."),y=b.split("\\.");for(int i=0;i<3;i++){int d=Integer.compare(Integer.parseInt(x[i]),Integer.parseInt(y[i]));if(d!=0)return d;}return 0;}
 static JSONObject verify(String envelope)throws Exception{if(envelope.length()>350000)throw new IOException("更新信息过大");JSONObject e=new JSONObject(envelope);byte[] raw=Base64.getDecoder().decode(e.getString("payload"));Signature signature=Signature.getInstance("SHA256withRSA");signature.initVerify(KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(UpdateKey.SPKI))));signature.update(raw);if(!signature.verify(Base64.getDecoder().decode(e.getString("signature"))))throw new IOException("更新签名不正确，已拒绝此线路");JSONObject p=new JSONObject(new String(raw,StandardCharsets.UTF_8));if(!"starcase-archive".equals(p.getString("app"))||p.getInt("schema")!=1)throw new IOException("不兼容的更新信息");compare(p.getString("version"),CURRENT);JSONObject a=p.getJSONObject("android");long size=a.getLong("size");if(size<1024||size>128L*1024*1024||!a.getString("sha256").matches("[a-f0-9]{64}"))throw new IOException("安装包校验信息无效");if(!a.getString("url").equals(REPO+"releases/download/v"+p.getString("version")+"/Starcase-Android.apk")||!a.getString("package").equals("com.starcase.archive")||a.getLong("versionCode")<1)throw new IOException("安装包地址或应用标识无效");return p;}
 static String prefix(String s)throws Exception{s=s.trim();if(s.isEmpty())return "";URI u=new URI(s);if(s.length()>200||!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)throw new IOException("自定义镜像需填写 HTTPS 地址前缀，不含账号、查询参数或文件地址");return s.replaceAll("/+$","")+"/";}
 static HttpURLConnection open(String url)throws Exception{for(int i=0;i<6;i++){URL u=new URL(url);if(!"https".equals(u.getProtocol()))throw new IOException("更新线路必须使用 HTTPS");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(8000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Starcase/"+CURRENT);c.setRequestProperty("Accept-Encoding","identity");int code=c.getResponseCode();if(code>=300&&code<400){String next=c.getHeaderField("Location");c.disconnect();url=new URL(u,next).toString();continue;}if(code!=200){c.disconnect();throw new IOException("线路返回 HTTP "+code);}return c;}throw new IOException("更新线路重定向过多");}
 static String read(String url)throws Exception{HttpURLConnection c=open(url);try(InputStream in=c.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();bytes.write(b,0,n);if(bytes.size()>350000)throw new IOException("更新信息格式错误");}return bytes.toString("UTF-8");}finally{c.disconnect();}}
 static String hash(File file)throws Exception{MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)hash.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:hash.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static void verifyFile(File file,JSONObject a)throws Exception{if(file.length()!=a.getLong("size")||!hash(file).equals(a.getString("sha256")))throw new IOException("安装包不完整或校验不通过，请重新下载");}
}
